using System.Text.Json;
using KorTrainer.Application.Common;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace KorTrainer.Infrastructure.Audio;

/// <summary>
/// Reads speech generated by tools/tts/generate_melo.py: a directory of Opus files and a manifest.json that
/// maps each text to its file. A missing directory simply means "no synthesized speech".
/// </summary>
public sealed class SynthesizedSpeechDirectory : ISynthesizedSpeech
{
    public const string ContentType = "audio/ogg";
    private const double DefaultSpeed = 1.0;

    private readonly string _directory;
    private readonly Lazy<Manifest> _manifest;

    public SynthesizedSpeechDirectory(IOptions<AudioOptions> options, ILogger<SynthesizedSpeechDirectory> logger)
    {
        _directory = Path.GetFullPath(options.Value.SynthesizedDirectory);
        _manifest = new Lazy<Manifest>(() => Load(_directory, logger));
    }

    public double GeneratedSpeed => _manifest.Value.Speed;

    public bool Has(string text) => _manifest.Value.Items.ContainsKey(text.Trim());

    public Task<AudioFile?> OpenAsync(string text, CancellationToken cancellationToken)
    {
        if (!_manifest.Value.Items.TryGetValue(text.Trim(), out string? key))
        {
            return Task.FromResult<AudioFile?>(null);
        }

        // Keys come from our own manifest (hex hashes), never from the caller.
        string path = Path.Combine(_directory, key + ".opus");
        return Task.FromResult(File.Exists(path)
            ? new AudioFile(File.OpenRead(path), ContentType)
            : null);
    }

    /// <summary>Parses manifest.json: {"speed": 0.9, "items": {"학교": "a1b2…"}}.</summary>
    public static Manifest Parse(Stream json)
    {
        var file = JsonSerializer.Deserialize<ManifestFile>(json, new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
        var items = (file?.Items ?? [])
            .Where(i => i.Value.Length > 0 && i.Value.All(Uri.IsHexDigit))
            .ToDictionary(i => i.Key.Trim(), i => i.Value, StringComparer.Ordinal);
        return new Manifest(file?.Speed is > 0 and var speed ? speed : DefaultSpeed, items);
    }

    private static Manifest Load(string directory, ILogger logger)
    {
        string path = Path.Combine(directory, "manifest.json");
        if (!File.Exists(path))
        {
            logger.LogInformation("No synthesized speech in {Directory}; the device's speech synthesis is used", directory);
            return new Manifest(DefaultSpeed, new Dictionary<string, string>());
        }

        using var stream = File.OpenRead(path);
        var manifest = Parse(stream);
        logger.LogInformation("Synthesized speech: {Count} texts from {Directory}", manifest.Items.Count, directory);
        return manifest;
    }

    public sealed record Manifest(double Speed, IReadOnlyDictionary<string, string> Items);

    private sealed record ManifestFile(double? Speed, Dictionary<string, string>? Items);
}
